import{_ as l,a0 as o,w as d,s as r,I as a,x as n,a1 as t,A as i,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"Systemd 服务：比启动停止服务更进一步 | LCTT x X-CMD","titleTemplate":false,"description":"Systemd 服务：比启动停止服务更进一步 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Systemd 服务：比启动停止服务更进一步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Systemd 服务：比启动停止服务更进一步 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180507 Systemd Services- Beyond Starting and Stopping","title":"Systemd 服务：比启动停止服务更进一步","tag":"201806","desc":""},"relativePath":"201806/20180507 Systemd Services- Beyond Starting and Stopping.md","filePath":"[post].md"}'),c={name:"201806/20180507 Systemd Services- Beyond Starting and Stopping.md"};function m(g,s,u,h,b,k){const e=o("Link");return d(),r("div",null,[s[21]||(s[21]=a("h1",{id:"systemd-服务-比启动停止服务更进一步",tabindex:"-1"},[n("Systemd 服务：比启动停止服务更进一步 "),a("a",{class:"header-anchor",href:"#systemd-服务-比启动停止服务更进一步","aria-label":"Permalink to “Systemd 服务：比启动停止服务更进一步”"},"​")],-1)),s[22]||(s[22]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/systemd-minetest-2.jpg?itok=bXO0ggHL",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("在上一篇",-1)),t(e,{href:"https://linux.cn/article-9700-1.html"},{default:i(()=>[...s[0]||(s[0]=[n("文章",-1)])]),_:1}),s[2]||(s[2]=n("中，我们展示了如何创建一个 systemd 服务并使普通用户可以启动和终止游戏服务器。但到目前为止，使用这个服务并不比直接运行服务器高明多少。让我们更进一步，让其可以向玩家发邮件，包括在服务器可用时通知玩家，在服务器关闭前警告玩家：",-1))]),s[23]||(s[23]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># minetest.service</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description= Minetest server</span></span>
<span class="line"><span>Documentation= https://wiki.minetest.net/Main_Page</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type= simple</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ExecStart= /usr/games/minetest --server</span></span>
<span class="line"><span>ExecStartPost= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Ready to rumble?&quot; &quot;Minetest Starting up&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TimeoutStopSec= 180</span></span>
<span class="line"><span>ExecStop= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Off to bed. Nightie night!&quot; &quot;</span></span>
<span class="line"><span>  Minetest Stopping in 2 minutes&quot;</span></span>
<span class="line"><span>ExecStop= /bin/sleep 120</span></span>
<span class="line"><span>ExecStop= /bin/kill -2 $MAINPID</span></span></code></pre></div><p>这里涉及几个新的指令。首先是 <code>ExecStartPost</code> 指令，该指令可以在主进程启动后马上执行任何你指定的操作。在本例中，你执行了一个自定义脚本 <code>mtsendmail</code> (内容如下)，该脚本以邮件形式通知你的朋友服务器已经启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span># mtsendmail</span></span>
<span class="line"><span>echo $1 | mutt -F /home/&lt;username&gt;/.muttrc -s &quot;$2&quot; my_minetest@mailing_list.com</span></span></code></pre></div>`,3)),a("p",null,[s[4]||(s[4]=n("我们使用 ",-1)),t(e,{href:"http://www.mutt.org/"},{default:i(()=>[...s[3]||(s[3]=[n("Mutt",-1)])]),_:1}),s[5]||(s[5]=n(" 这个命令后邮件客户端发送消息。虽然从实际效果来看，上述脚本仅有 1 行，但 systemd 单元的参数中不能包含管道及重定向操作，故我们需要将其封装到脚本中。",-1))]),s[24]||(s[24]=p(`<p>顺便提一下，还有一个 <code>ExecStartPre</code> 指令，用于在服务主进程执行之前进行指定操作。</p><p>接下来我们看到，关闭服务器涉及了好几条指令。<code>TimeoutStopSec</code> 指令用于设置 systemd 友好关闭服务的最大等候时间，默认值大约是 90 秒。超过这个最大等候时间，systemd 会强制关闭服务并报错。考虑到你希望在彻底关闭服务器前给用户预留几分钟的时间，你需要将超时时间提高至 3 分钟，这样 systemd 就不会误认为服务关闭时出现问题。</p><p>接下来是关闭服务的具体指令部分。虽然没有 <code>ExecStopPre</code> 这样的指令，但你可以通过多次使用 <code>ExecStop</code> 指令实现关闭服务器前执行操作的目标。多个 <code>ExecStop</code> 指令按从上到下的顺序依次运行，这样你就可以在服务器真正关闭前向用户发送消息。</p><p>通过这个特性，你首先应该向你的朋友发邮件，警告其服务器即将关闭，然后等待两分钟，最后关闭服务器。可以使用 <code>Ctrl + c</code> 关闭 Minetest 服务器，该操作会被转换为一个中断信号（<code>SIGINT</code>）；当你执行 <code>kill -2 $MAINPID</code> 时就会发送该中断信号，其中 <code>$MAINPID</code> 是 systemd 变量，用于记录你服务中主进程的 PID 信息。</p><p>看上去好多了！如果你此时启动服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl --user start minetest</span></span></code></pre></div><p>服务会启动 Minetest 服务器并向你的用户发送邮件。关闭服务的情形基本类似，只不过会额外留给用户 2 分钟时间退出登录。</p><h3 id="开机自启动" tabindex="-1">开机自启动 <a class="header-anchor" href="#开机自启动" aria-label="Permalink to “开机自启动”">​</a></h3><p>下一步我们让你的服务在主机启动后立即可用，在主机关闭时自动关闭。</p><p>我们需要将你的服务文件移动到系统服务目录，即 <code>/etc/systemd/system/</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mv /home/&lt;username&gt;/.config/systemd/user/minetest.service /etc/systemd/system/</span></span></code></pre></div><p>如果你希望此时启动该服务，你需要拥有超级用户权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start minetest</span></span></code></pre></div><p>另外，可以使用如下命令检查服务状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl status minetest</span></span></code></pre></div><p>你会发现服务很糟糕地处于失败状态，这是因为 systemd 不能通过上下文信息、特征、配置文件得知具体使用哪个用户运行该服务。在单元文件中增加 <code>User</code> 指令可以解决这个问题。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># minetest.service</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description= Minetest server</span></span>
<span class="line"><span>Documentation= https://wiki.minetest.net/Main_Page</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type= simple</span></span>
<span class="line"><span>User= &lt;username&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ExecStart= /usr/games/minetest --server</span></span>
<span class="line"><span>ExecStartPost= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Ready to rumble?&quot;</span></span>
<span class="line"><span>  &quot;Minetest Starting up&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TimeoutStopSec= 180</span></span>
<span class="line"><span>ExecStop= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Off to bed. Nightie night!&quot;</span></span>
<span class="line"><span>  &quot;Minetest Stopping in 2 minutes&quot;</span></span>
<span class="line"><span>ExecStop= /bin/sleep 120</span></span>
<span class="line"><span>ExecStop= /bin/kill -2 $MAINPID</span></span></code></pre></div><p>systemd 从 <code>User</code> 指令中得知应使用哪个用户的环境变量来正确运行该服务。你可以使用 root 用户，但这可能产生安全风险；使用你的个人用户会好一些，但不少管理员的做法是为服务单独创建一个用户，这样可以有效地将服务与其它用户和系统组件相互隔离。</p><p>下一步我们让你的服务在系统启动时自动启动，系统关闭时自动关闭。要达到这个目的，你需要 <em>启用</em> 你的服务；但在这之前，你还需要告知 systemd 从哪里 <em>安装</em> 它。</p><p>对于 systemd 而言，<em>安装</em> 意味着告知 systemd 在系统启动的具体哪个步骤激活你的服务。以通用 Unix 打印系统（<code>cups.service</code>）为例，它的启动在网络框架启动之后、其它打印服务启动之前。又如，<code>minetest.server</code> 需要使用用户邮件（及其它组件），需要等待网络和普通用户对应的服务就绪后才可启动。</p><p>你只需要在单元文件中添加一个新段和新指令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy= multi-user.target</span></span></code></pre></div><p>你可以将其理解为“等待多用户系统的全部内容就绪”。systemd 中的“目标”类似于旧系统中的运行级别，可以用于将主机转移到一个或另一个状态，也可以像本例中这样让你的服务等待指定状态出现后运行。</p><p>你的最终 <code>minetest.service</code> 文件如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># minetest.service</span></span>
<span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description= Minetest server</span></span>
<span class="line"><span>Documentation= https://wiki.minetest.net/Main_Page</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type= simple</span></span>
<span class="line"><span>User= &lt;username&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ExecStart= /usr/games/minetest --server</span></span>
<span class="line"><span>ExecStartPost= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Ready to rumble?&quot;</span></span>
<span class="line"><span>  &quot;Minetest Starting up&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TimeoutStopSec= 180</span></span>
<span class="line"><span>ExecStop= /home/&lt;username&gt;/bin/mtsendmail.sh &quot;Off to bed. Nightie night!&quot;</span></span>
<span class="line"><span>  &quot;Minetest Stopping in 2 minutes&quot;</span></span>
<span class="line"><span>ExecStop= /bin/sleep 120</span></span>
<span class="line"><span>ExecStop= /bin/kill -2 $MAINPID</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy= multi-user.target</span></span></code></pre></div><p>在尝试新的服务之前，你还需要对邮件脚本做一些调整：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span># mtsendmail</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sleep 20</span></span>
<span class="line"><span>echo $1 | mutt -F /home/&lt;username&gt;/.muttrc -s &quot;$2&quot; my_minetest@mailing_list.com</span></span>
<span class="line"><span>sleep 10</span></span></code></pre></div><p>这是因为系统需要一定的时间启动邮件系统（这里等待 20 秒），也需要一定时间完成邮件发送（这里等待 10 秒）。注意脚本中的等待时间数值适用于我的系统，你可能需要针对你的系统调整数值。</p><p>大功告成啦。执行如下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable minetest</span></span></code></pre></div><p>你的 Minetest 服务将在系统启动时自动启动，在系统关闭时友好关闭并通知你的用户。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>事实上 Debian、 Ubuntu 和一些族类的发行版提供了 <code>minetest-server</code> 这个特别的软件包，可以提供一部分上述功能，（但不包括邮件通知功能）。即使如此，你还是可以建立你独有的自定义服务；事实上，你目前建立的服务比 Debian 默认提供的服务更加通用，可以提供更多功能。</p><p>更进一步的说，我们这里描述的流程可以让你将大多数简单服务器转换为服务，类型可以是游戏、网站应用或其它应用。同时，这也是你名副其实地踏入 systemd 大师殿堂的第一步。</p><hr>`,35)),a("p",null,[s[7]||(s[7]=n("via: ",-1)),t(e,{href:"https://www.linux.com/blog/learn/2018/5/systemd-services-beyond-starting-and-stopping"},{default:i(()=>[...s[6]||(s[6]=[n("https://www.linux.com/blog/learn/2018/5/systemd-services-beyond-starting-and-stopping",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=n("作者：",-1)),t(e,{href:"https://www.linux.com/users/bro66"},{default:i(()=>[...s[8]||(s[8]=[n("Paul Brown",-1)])]),_:1}),s[13]||(s[13]=n(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[9]||(s[9]=[n("lujun9972",-1)])]),_:1}),s[14]||(s[14]=n(" 译者：",-1)),t(e,{href:"https://github.com/pinewall"},{default:i(()=>[...s[10]||(s[10]=[n("pinewall",-1)])]),_:1}),s[15]||(s[15]=n(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[11]||(s[11]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[16]||(s[16]=[n("LCTT",-1)])]),_:1}),s[19]||(s[19]=n(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[17]||(s[17]=[n("Linux中国",-1)])]),_:1}),s[20]||(s[20]=n(" 荣誉推出",-1))])])}const x=l(c,[["render",m]]);export{S as __pageData,x as default};
